mapper.delete:
DELETE FROM saved_jobs
WHERE user_id = #{userId}
  AND job_posting_id = #{jobPostingId}

mapper.select:
SELECT c.company_id, c.company_name, c.industry_name, c.company_size, c.logo_url, (SELECT COUNT(*) FROM job_postings jp WHERE jp.company_id = c.company_id AND jp.status = '모집중' AND (jp.apply_end_at IS NULL OR jp.apply_end_at >= CURRENT_DATE)) AS jobPostingCount FROM saved_companies sc JOIN companies c ON c.company_id = sc.company_id WHERE sc.user_id = #{userId} AND c.company_status = '정상' AND c.approval_status = '승인'
ORDER BY c.company_name ASC ORDER BY jobPostingCount DESC, sc.created_at DESC ORDER BY sc.created_at DESC
LIMIT #{offset}, #{pageSize}

mapper.delete:
DELETE FROM saved_companies
WHERE user_id = #{userId}
  AND company_id = #{companyId}
